require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_sales_access();$q=trim($_GET['q']??'');$stage=(int)($_GET['stage']??0);$source=(int)($_GET['source']??0);$priority=trim($_GET['priority']??'');$assigned=(int)($_GET['assigned']??0);$clientCategory=trim($_GET['client_category']??'');$clientLabel=trim($_GET['client_label']??'');$where=[];$params=[];$visibility=lead_visibility_sql($params,'l');if($q!==''){$where[]='(l.name LIKE ? OR l.company LIKE ? OR l.email LIKE ? OR l.contact LIKE ? OR l.message LIKE ?)';$like="%$q%";array_push($params,$like,$like,$like,$like,$like);}if($stage>0){$where[]='l.stage_id=?';$params[]=$stage;}if($source>0){$where[]='l.source_id=?';$params[]=$source;}if(in_array($priority,lead_priorities(),true)){$where[]='l.priority=?';$params[]=$priority;}if($assigned>0){$where[]='l.assigned_to=?';$params[]=$assigned;}if(in_array($clientCategory,['Current Client','Old Client','Client Left','Prospect'],true)){$where[]='l.client_category=?';$params[]=$clientCategory;}if(in_array($clientLabel,['Hot','Cold','Dead'],true)){$where[]='l.client_label=?';$params[]=$clientLabel;}$sql='SELECT l.id,l.name,l.company,l.email,l.contact,l.message,l.status,l.priority,l.client_category,l.client_label,ls.name source,ps.name stage,u.username assigned_to,l.follow_up_date,l.notes,l.created_at FROM leads l LEFT JOIN lead_sources ls ON ls.id=l.source_id LEFT JOIN pipeline_stages ps ON ps.id=l.stage_id LEFT JOIN users u ON u.id=l.assigned_to'.($where?' WHERE '.implode(' AND ',$where):'').$visibility.' ORDER BY l.created_at DESC';$s=$pdo->prepare($sql);$s->execute($params);header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="webisdom-b2b-leads-'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');fputcsv($out,['ID','Name','Company','Email','Contact','Message','Legacy Status','Priority','Client Category','Client Label','Lead Source','Pipeline Stage','Assigned To','Follow-up Date','Notes','Created At']);while($r=$s->fetch())fputcsv($out,$r);fclose($out);exit;
